import { integer, jsonb, pgTable, text, timestamp, uuid, varchar } from 'drizzle-orm/pg-core'

import { users } from './auth'
import { activities } from './content'

/**
 * The operator who runs an activity, and its contract (migration 0036,
 * owner, Oct 2026). STAFF ONLY: no public query reads this table, and the
 * contract PDF lives in private storage (`contract_key`), downloaded only
 * through the Studio route `activities/[id]/contract`.
 *
 * `contract_summary` is an AI summary (OpenRouter) of the PDF text, shown in
 * the editor marked «generated by AI — needs a human review».
 */
export interface ContractSummary {
  prices: string
  paymentTerms: string
  cancellation: string
  liabilities: string
  duration: string
  redFlags: string[]
  other: string
}

export const activityOperators = pgTable('activity_operators', {
  activityId: uuid('activity_id')
    .primaryKey()
    .references(() => activities.id, { onDelete: 'cascade' }),
  name: varchar('name', { length: 200 }).notNull().default(''),
  contactPerson: varchar('contact_person', { length: 200 }).notNull().default(''),
  phone: varchar('phone', { length: 40 }).notNull().default(''),
  email: varchar('email', { length: 200 }).notNull().default(''),
  commissionNotes: text('commission_notes').notNull().default(''),
  cancellationTerms: text('cancellation_terms').notNull().default(''),
  contractKey: text('contract_key'),
  contractFilename: varchar('contract_filename', { length: 200 }),
  contractBytes: integer('contract_bytes'),
  contractUploadedAt: timestamp('contract_uploaded_at', { withTimezone: true }),
  contractUploadedBy: uuid('contract_uploaded_by').references(() => users.id, {
    onDelete: 'set null',
  }),
  contractSummary: jsonb('contract_summary').$type<ContractSummary>(),
  summaryModel: varchar('summary_model', { length: 120 }),
  summaryAt: timestamp('summary_at', { withTimezone: true }),
  updatedAt: timestamp('updated_at', { withTimezone: true }).notNull().defaultNow(),
})
